// I-9 (Rev. 08/01/23) AcroForm field definitions.
// Coordinates are in PDF points (pt): x/y measured from bottom-left of the page.
// Page height = 792 pt. Field names match the exact AcroForm field names in the PDF.
// Generated by scripts/discover-i9-fields.mjs against the official USCIS PDF.

export interface I9FieldDef {
  page: number;         // 1-indexed
  x: number;           // distance from left edge, pt
  y: number;           // distance from bottom edge, pt
  w: number;           // width, pt
  h: number;           // height, pt
  fieldName: string;   // exact AcroForm field name for pdf-lib filling
}

// ── Page dimensions ────────────────────────────────────────────────────────────
export const PDF_PAGE_WIDTH  = 612;   // letter, pt
export const PDF_PAGE_HEIGHT = 792;   // letter, pt

