// ── Section 2 — Employer Review (Page 1, bottom half; employer fills post-hire) ─
// These coordinates are shown as locked overlays in the employee's view.
// Employer fields at y < 420 on page 1, and additional content on page 4.
export const I9_SECTION1_BOUNDARY_Y = 420;   // fields below this y are employer territory

// ── Coordinate transform ───────────────────────────────────────────────────────
// Converts PDF field coordinates to CSS pixel position within a rendered canvas.
// PDF origin is bottom-left; CSS origin is top-left — so Y must be flipped.
export function pdfToScreen(
  field: I9FieldDef,
  scale: number,
  pageHeight = PDF_PAGE_HEIGHT,
): { left: number; top: number; width: number; height: number } {
  return {
    left:   field.x * scale,
    top:    (pageHeight - field.y - field.h) * scale,
    width:  field.w * scale,
    height: field.h * scale,
  };
}
